INSERT INTO contents (title, category, genre, synopsis, thumbnail_url, total_seasons, total_episodes) VALUES
('눈물의 여왕', '드라마', '로맨스/드라마', '재벌가 딸과 촌동네 아들의 위기와 사랑 이야기. 결혼 3년차 부부가 이혼 위기 속에서 사랑을 찾아가는 감동 드라마.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNDA0MTBfMTAz%2FMDAxNzEyNzIxNDA0MjQx.EessV7FuRA8uTk6r_LyfZIAMo2n1SjBp-mI4dtqZgVog.AtqUr90Fk1t9MV_La3tuNh8XqyaOg7-FJBnf-KGZVKUg.PNG%2Fimage.png&type=sc960_832', 1, 16),
('선재 업고 튀어', '드라마', '로맨스/판타지', '타임슬립을 통해 첫사랑을 구하려는 여자의 이야기. 과거로 돌아간 그녀는 운명을 바꿀 수 있을까?', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNDAzMjhfNTgg%2FMDAxNzExNjI0MjgzNDYy.FYxBzrmbaavQhn9hqw-IvjvYQVJKTEt8KjQg7Fr6DV4g.rEn7l9Alq3lnXTqrxR0-Zq7mn3FEMPEdNgH-D2-_DgUg.JPEG%2F37e63b66843b4b3d843dc11486634500.jpg&type=sc960_832', 1, 16),
('무인도의 디바', '드라마', '드라마/음악', '무인도에서 15년을 보낸 여성이 구조 후 가수의 꿈을 향해 나아가는 이야기.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Fimg.extmovie.com%2Ffiles%2Fattach%2Fimages%2F135%2F013%2F557%2F091%2F42fcfa8d3c9c23f11d08b7ee1870c0b4.jpg&type=sc960_832', 1, 12),
('재벌집 막내아들', '드라마', '판타지/드라마', '억울하게 죽은 재벌가 비서가 막내 손자로 환생하여 복수를 꿈꾸는 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMjEwMjVfMjY5%2FMDAxNjY2Njk3ODk3MjYw.SxDVJRaQpfQVQ1KdECoMjfTTTiLhpIva2J-6lQqvl08g.h3HB6gNxX2d7OyQxGwtVG0wQD3WHrg5QvsLOeHtGDxMg.PNG.limjoj2001%2Fimage.png&type=a340', 1, 16),
('이상한 변호사 우영우', '드라마', '법정/드라마', '자폐 스펙트럼 장애를 가진 천재 변호사가 대형 로펌에서 성장하며 편견에 맞서는 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMjA3MDhfMjQ5%2FMDAxNjU3MjMyMjY0NDc5.18JqgjtAqMRxCpotRK1D4zxy4BzTopTAmHmsqiGayM0g.rPkexq6cLj9yz0OTsqU7qqpla0M8q1DWQZqTvb43AoYg.JPEG.bigmouth978%2FScreenshot%25A3%25DF20220708%25A3%25AD070220.jpg&type=a340', 1, 16),
('킹덤', '드라마', '사극/좀비스릴러', '조선시대를 배경으로 좀비 역병이 퍼지는 가운데 왕위를 둘러싼 음모와 사투.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fimgnews.naver.net%2Fimage%2F5041%2F2020%2F12%2F03%2F0000637500_001_20201203144726906.jpg&type=a340', 2, 12),
('시그널', '드라마', '범죄/판타지', '과거와 현재를 잇는 무전기를 통해 미제 사건을 해결하는 형사들의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2F20160315_150%2Fhakcheol11_1458024046680s3HxR_JPEG%2F%25B2%25D9%25B9%25CC%25B1%25E2_%25BD%25C3%25B1%25D7%25B3%25CE1.jpg&type=a340', 1, 16),
('슬기로운 의사생활', '드라마', '의학/힐링', '20년 지기 친구 5명이 의사로서 환자를 치료하며 소소한 행복을 찾는 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMDA1MjlfMzAw%2FMDAxNTkwNzUwNTAzMDkx.-VP4SXhK8VZ_5WUYcasQbMvIXsJ0DLlY4yWByapSUwMg.yeylfHdjcIQxrlpsEZ-6cMpa3lGTus0JREcqD7T-M6Qg.JPEG.1998310906%2F1590750502953.jpg&type=a340', 2, 12),
('비밀의 숲', '드라마', '법정/스릴러', '감정을 느끼지 못하는 검사와 정의로운 경찰이 거대한 비리를 파헤치는 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAxNzA3MzFfNjMg%2FMDAxNTAxNTEyMjEzNTIz.JVYnxLSHKNzLPQr6xhIPaqmA1_kYGebJDvvr9IIgRikg.gIigETPcVkktC_-jCRAaSVBXdFc0fl6Mt7qnzRX3ewsg.JPEG.idoyun116%2F99964d17-18f6-495d-a11c-f05bc32c8f1f.jpg&type=a340', 2, 16),
('미스터리 수사단: 실종', '드라마', '스릴러/미스터리', '실종 사건을 전문으로 다루는 특수 수사팀의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNDA2MTlfNTgg%2FMDAxNzE4NzkwOTU0NDA2.X07A4CXryIP45HWGqzBvOUNrbNqVeUC_RiMqf265RJQg.QFA4We22mtwghDdmT3sJVtAySyEzvj4UWAqNI_Ve1fwg.JPEG%2F1718790953657.jpg&type=a340', 1, 12);
INSERT INTO contents (title, category, genre, synopsis, thumbnail_url, total_seasons, total_episodes) VALUES
('파묘', '영화', '미스터리/공포', '미국 LA에서 원인 모를 병에 시달리는 집안의 묘를 이장하면서 벌어지는 초자연적 사건.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNDAyMjJfMTU2%2FMDAxNzA4NTg5NjE4MjU0.-q_ibSaGGSzhWJWYRlXjYa3bkDsjhIjRbqguz84V7AYg.JdcZpHU8VoWkkBOmtxkZkIbDAWCDnQcbGxinLVP1gAMg.JPEG%2Foutput_282173849.jpg&type=a340', 1, 1),
('서울의 봄', '영화', '드라마/역사', '1979년 12.12 군사반란의 실화를 바탕으로 민주주의를 지키려 한 군인들의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNTAxMjhfMTQz%2FMDAxNzM4MDYyODk2NjA3.lkmHgIjIcV5EYq3N-_b8j933Cpsi1AmkL0JZ2gpBlzcg.6Aiu0u_2NXLU-x2M6Qsq3VyUrW81xmcsp16ew1FlRS8g.JPEG%2F650%25A3%25DF20250128%25A3%25DF200838.jpg&type=a340', 1, 1),
('범죄도시 3', '영화', '액션/범죄', '괴물형사 마석도가 일본 야쿠자와 연계된 마약 조직을 소탕하는 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMzA1MTRfMjIw%2FMDAxNjg0MDQxODQzOTQy.qAshWcyUpdqBBI4KczFiwdyWWiGSikHYI88qQDNeQuIg.8nPRsEiN0jkuPody_sK06VZFMX6gizhlQi3RlPDOsf0g.PNG.screem33%2F20230514_142333_20.png&type=a340', 1, 1),
('콘크리트 유토피아', '영화', 'SF/스릴러', '대지진 후 유일하게 남은 아파트에서 벌어지는 생존자들의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMzA5MDVfMjIz%2FMDAxNjkzODc0MjUxNTUx.wVK1d6hqvZpwwvtX8VHmkeW6cf5gUY_fNQC2qz0mQ70g.cDNvwMxXShsH41LHB-lO-vW3N9DjwsyI7xcRL7ulOdYg.JPEG.cdhun600118%2F1693874251019.jpg&type=a340', 1, 1),
('밀수', '영화', '범죄/드라마', '1970년대 해녀 마을을 배경으로 밀수에 휘말린 두 여성의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMzExMDJfNTEg%2FMDAxNjk4OTA3ODY2MDI2.eGsFtFNZUP_uwTxjo2otYPJ440ltuq0CKtsR1b8Rzwcg.sZjZhYKAH92MUjqpNoIj457keKKcIElxxhCY2BeiqzQg.JPEG.valuesarah%2F1.jpg&type=a340', 1, 1),
('오펜하이머', '영화', '전기/드라마', '원자폭탄 개발을 이끈 물리학자의 삶과 도덕적 딜레마를 그린 역작.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMzA4MTZfMTc3%2FMDAxNjkyMTkwMjIyMzc2.zS866ICrExau-WyOrkcpzRm9QmNlv7swhigcX8aO0YMg.upZnawGfnkqs2I_NIj1bbfM1V-zx1HtmSA5kYLp761kg.JPEG.illierd83%2F1692190222287.jpg&type=a340', 1, 1),
('스즈메의 문단속', '영화', '애니메이션/판타지', '일본 각지에 나타나는 재앙의 문을 닫아가는 소녀의 여정.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Fimg.flayus.com%2Ffiles%2Fattach%2Fimages%2F60017%2F998%2F435%2F106%2F1620dd45616cf181d416581e2d930b62.jpg&type=a340', 1, 1),
('가디언즈 오브 갤럭시 3', '영화', 'SF/액션', '가디언즈 팀의 마지막 모험. 로켓의 과거가 밝혀지며 팀이 위기에 처한다.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNjA1MDFfMTk3%2FMDAxNzc3NjQwMDIyNzU0.NJAowrds6BKEyhbbAggVXTKTfN4C7TT3xky3vAeeLdwg.U6IU7OUFwXA89JlYCbU5-ahGHOqJZ8Wwt5Zc-NUXWZcg.JPEG%2F%25BD%25BA%25C5%25A9%25B8%25B0%25BC%25A6_1-5-2026_215146_search.naver.com.jpeg&type=a340', 1, 1),
('엘리멘탈', '영화', '애니메이션/로맨스', '불, 물, 땅, 공기 원소들이 사는 도시에서 두 원소의 사랑 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMzA2MTVfNjEg%2FMDAxNjg2ODIzMDQ1NjM0.atkGd0dipFtgklJp0EKx6NxYvhMtPyQsBNpkFUpvo0wg.hFirSCcw1sUvqiL1owHOImfEc_L2awZympKOMEKGWx4g.JPEG.kcl310302%2FIMG_0992.JPG&type=a340', 1, 1),
('외계+인 2부', '영화', 'SF/판타지', '고려시대와 현대를 오가며 외계인과 도사의 대결을 그린 SF 판타지.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNDAxMTZfMzgg%2FMDAxNzA1NDAzNTUyMTc5.T3D3GWFWKFItvPJ0OF0sL8nAae7g3Emq620fCg8W0f0g.VGM1BJgiz4-v9Q85noq67yf-2TTsCaz12PiwgVo2uZIg.JPEG.ssoongnim%2Foutput_692382292.jpg&type=a340', 1, 1);
INSERT INTO contents (title, category, genre, synopsis, thumbnail_url, total_seasons, total_episodes) VALUES
('나는 솔로', '예능', '리얼리티/연애', '솔로 남녀가 만나 사랑을 찾아가는 리얼리티 연애 프로그램.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fimgnews.naver.net%2Fimage%2F5575%2F2021%2F07%2F05%2F0000212296_001_20210705092423907.png&type=a340', 1, 20),
('환승연애 3', '예능', '리얼리티/연애', '전 연인과 새로운 인연 사이에서 선택하는 연애 리얼리티.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Ffimg5.pann.com%2Fnew%2Fdownload.jsp%3FFileID%3D67251289&type=a340', 1, 16),
('신서유기', '예능', '코미디/여행', '게임과 미션으로 가득한 여행 예능. 출연진의 케미가 매력적.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Fimg1.daumcdn.net%2Fthumb%2FR720x0%2F%3Ffname%3Dhttp%3A%2F%2Ft1.daumcdn.net%2Fliveboard%2Fenter%2F7d53cced0783406998b38dc947fa3603.JPG&type=a340', 9, 10),
('놀라운 토요일', '예능', '음악/퀴즈', '노래 받아쓰기와 맛집 투어를 즐기는 토요 예능.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAxODA0MTZfMTY2%2FMDAxNTIzODU5ODQwMzE3.l81GfAoFdIKDEoDGmfxfgxSrbb9pQKfyCe_kI87_oh8g.oiqJtiKJPirQ67crO1d32IbGz6MoazWgA-cHYoSkkSEg.JPEG.pkm92423%2F%25C7%25FD%25B8%25AE-%25B3%25EE%25B6%25F3%25BF%25EE_%25C5%25E4%25BF%25E4%25C0%25CF-%25C6%25F7%25BD%25BA%25C5%25CD.jpg&type=a340', 1, 30),
('삼시세끼', '예능', '쿡방/힐링', '자연 속에서 하루 세 끼를 직접 해먹는 힐링 예능.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fimgnews.naver.net%2Fimage%2F433%2F2016%2F06%2F17%2F20160617105646_4474417637906_99_20160617110603.jpg&type=a340', 5, 10),
('유 퀴즈 온 더 블럭', '예능', '토크/다큐', '길 위에서 만난 사람들의 이야기를 듣는 토크쇼.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fimgnews.naver.net%2Fimage%2F112%2F2018%2F08%2F16%2F201808161049093703062_20180816104959_01_20180816105208449.jpg&type=a340', 1, 50),
('짠내투어', '예능', '여행/코미디', '최소 비용으로 최대 즐거움을 추구하는 가성비 여행 예능.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fimgnews.naver.net%2Fimage%2F144%2F2017%2F11%2F09%2F0000521968_001_20171109104436955.jpg&type=a340', 1, 20),
('강식당', '예능', '쿡방/코미디', '셰프 강호동과 출연진이 운영하는 식당 리얼리티.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fimgnews.naver.net%2Fimage%2F5129%2F2019%2F05%2F20%2F201458598_20190520155020283.jpg&type=a340', 3, 10);
INSERT INTO contents (title, category, genre, synopsis, thumbnail_url, total_seasons, total_episodes) VALUES
('한반도의 공룡', '다큐', '자연/과학', '한반도에 살았던 공룡들의 흔적을 추적하는 대형 자연 다큐멘터리.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2F20120224_44%2Fpinkrose0713_1330044518703xBgHw_JPEG%2F1.jpg&type=a340', 1, 4),
('나의 해방일지', '다큐', '라이프/힐링', '바쁜 일상 속에서 해방을 찾아가는 현대인들의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyMjA0MTlfNzcg%2FMDAxNjUwMzQwNDgxMzA2.-__XNoYRlgy687jlG61N_b7nnhqO8HKdAIue5j251mwg.vnBtP8EuZCP6yfRfgxUf9ig-CW2OSgD5diq1UZUdV44g.JPEG.asdzxcqwe04%2FIMG_4408.JPG&type=a340', 1, 6),
('지구의 숨결', '다큐', '자연/환경', '기후변화로 위협받는 지구 생태계의 현실을 보여주는 환경 다큐.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Fcontents.kyobobook.co.kr%2Fsih%2Ffit-in%2F458x0%2Fpdt%2F9791197330667.jpg&type=a340', 1, 8),
('한국인의 밥상', '다큐', '요리/문화', '전국 각지의 식문화와 사람들의 이야기를 담은 음식 다큐.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Fimage.aladin.co.kr%2Fproduct%2F1397%2F5%2Fcover500%2F899397666x_1.jpg&type=a340', 1, 20),
('우주로의 여행', '다큐', '과학/우주', '인류의 우주 탐사 역사와 미래 계획을 다룬 과학 다큐멘터리.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2F20160213_282%2Fk13hey_145534139837120KUa_JPEG%2F20160211155008775rdir.jpg&type=a340', 1, 6);
INSERT INTO contents (title, category, genre, synopsis, thumbnail_url, total_seasons, total_episodes) VALUES
('귀멸의 칼날', '애니', '액션/판타지', '가족을 잃은 소년이 귀신 사냥꾼이 되어 여동생을 구하기 위한 여정.', 'https://search.pstatic.net/sunny/?src=https%3A%2F%2Fcontents.oricon.co.jp%2Fupimg%2Fnews%2F2403000%2F2402991%2F20250825_002426_p_l_80916091.jpg&type=a340', 4, 12),
('주술회전', '애니', '액션/다크판타지', '저주로 생겨난 괴물들과 싸우는 주술사들의 이야기.', 'https://search.pstatic.net/common/?src=http%3A%2F%2Fblogfiles.naver.net%2FMjAyNjA0MDFfNTgg%2FMDAxNzc1MDIzMzAwNjE3.DVq5tq2hQ2RnAZM3YZjSuXxKgZxLyU0Y6DV29CSKYi0g.zic9PlSo6BeAT8N9zUszwAxiLOsTQlbEgR2A_PP_qVYg.JPEG%2FP001781419.jpg&type=a340', 2, 24),
